pm.sendRequest({
  url: pm.collectionVariables.get("baseUrl") + "/api/auth/login",
  method: "POST",
  header: [{ key: "Content-Type", value: "application/json" }],
  body: { mode: "raw", raw: JSON.stringify({
    username: pm.collectionVariables.get("loginUsername"),
    password: pm.collectionVariables.get("loginPassword")
  })}
}, (err, res) => {
  if (!err && res && res.json && res.json().ok) {
    pm.collectionVariables.set("sessionToken", res.json().role || "staff");
  }
});

